    this.tahun = tahun;
    this.rating = rating;
  }
}
const f1 = new Film("Laskar Pelangi", 2008, 8);
const f2 = new Film("Gundala", 2019);
console.log(`${f1.judul} (${f1.tahun}) rating ${f1.rating}`);
